const fs = require('fs');

const epFiles = fs.readdirSync('/results')
  .filter(f => f.endsWith('_endpoints.json'))
  .map(f => ({ name: f, mtime: fs.statSync(`/results/${f}`).mtime.getTime() }))
  .sort((a, b) => b.mtime - a.mtime);

if (epFiles.length === 0) throw new Error('No endpoints.json found');

const discovery = JSON.parse(fs.readFileSync(`/results/${epFiles[0].name}`, 'utf8'));
console.log(`Loaded: ${discovery.runId}, baseUrl=${discovery.baseUrl}, openApiUrl=${discovery.openApiUrl}`);

return [{ json: discovery }];

const cfg = $('Read Endpoints File').first().json;
const fs = require('fs');

await new Promise(r => setTimeout(r, 2000));

let normalized = [];
let stats = { total: 0, failures: 0, errors: 0, skipped: 0 };

const file = cfg.schemathesisOut;

if (fs.existsSync(file)) {
  try {
    const xml = fs.readFileSync(file, 'utf8');

    const tsMatch = xml.match(/<testsuites[^>]*errors="(\d+)"[^>]*failures="(\d+)"[^>]*skipped="(\d+)"[^>]*tests="(\d+)"/);
    if (tsMatch) {
      stats.errors   = parseInt(tsMatch[1]);
      stats.failures = parseInt(tsMatch[2]);
      stats.skipped  = parseInt(tsMatch[3]);
      stats.total    = parseInt(tsMatch[4]);
    }

    const re = /<testcase\s+name="([^"]*)"\s+time="([^"]*)"[^>]*>([\s\S]*?)<\/testcase>/g;
    let m;
    while ((m = re.exec(xml)) !== null) {
      const fullName = m[1];
      const time = parseFloat(m[2]) || 0;
      const body = m[3];

      const isFail  = body.includes('<failure');
      const isError = body.includes('<error');
      if (!isFail && !isError) continue;

      const parts = fullName.split(' ');
      const method = parts[0];
      const path = parts.slice(1).join(' ') || fullName;

      const msgMatch = body.match(/<(?:failure|error)[^>]*>([\s\S]*?)<\/(?:failure|error)>/);
      let message = '';
      if (msgMatch) {
        message = msgMatch[1]
          .replace(/1\. Test Case ID:[^\n]*\n/g, '')
          .replace(/Reproduce with:[\s\S]*$/m, '')
          .replace(/\s+/g, ' ')
          .trim()
          .slice(0, 500);
      }

      normalized.push({
        tool: 'schemathesis',
        method,
        endpoint: path,
        payload: fullName,
        status: 0,
        length: 0,
        time_ms: Math.round(time * 1000),
        message,
        isFailure: isFail,
        isError: isError,
      });
    }

    console.log(`Schemathesis: ${normalized.length} findings, stats:`, stats);
  } catch (e) {
    console.error('Schemathesis parse error:', e.message);
  }
} else {
  console.log('Schemathesis file not found:', file);
}

return [{ json: { ...cfg, schemathesisResults: normalized, schemathesisStats: stats }}];

const cfg = $('Read Endpoints File').first().json;
const fs = require('fs');
const path = require('path');

await new Promise(r => setTimeout(r, 3000));

const normalized = [];
let stats = { total: 0, failures: 0, errors: 0, skipped: 0 };

// Ищем папку cats_report_<runId>
const reportDir = `/results/cats_report_${cfg.runId}`;

if (fs.existsSync(reportDir)) {
  console.log('CATS dir found:', reportDir);

  const files = fs.readdirSync(reportDir).filter(f => f.endsWith('.xml'));

  for (const file of files) {
    try {
      const xml = fs.readFileSync(path.join(reportDir, file), 'utf8');

      const m = xml.match(/<testsuites[^>]*skipped="(\d+)"[^>]*errors="(\d+)"[^>]*failures="(\d+)"[^>]*tests="(\d+)"/);
      if (m) {
        stats.skipped  = parseInt(m[1]);
        stats.errors   = parseInt(m[2]);
        stats.failures = parseInt(m[3]);
        stats.total    = parseInt(m[4]);
      }

      const re = /<testcase\s+name="([^"]*)"\s+classname="([^"]*)"[^>]*>([\s\S]*?)<\/testcase>/g;
      let tc;
      while ((tc = re.exec(xml)) !== null) {
        const body = tc[3];
        const isFail  = body.includes('<failure');
        const isError = body.includes('<error');
        if (!isFail && !isError) continue;

        const msgMatch = body.match(/<(?:failure|error)[^>]*>([\s\S]*?)<\/(?:failure|error)>/);
        normalized.push({
          tool: 'cats',
          endpoint: tc[2],
          payload: tc[1],
          status: 0,
          isFailure: isFail,
          isError: isError,
          message: msgMatch ? msgMatch[1].replace(/\s+/g, ' ').trim().slice(0, 200) : '',
        });

        if (normalized.length >= 50) break;
      }
    } catch (e) {
      console.error('CATS parse error:', e.message);
    }
  }
} else {
  console.log('CATS dir not found:', reportDir);
}

console.log(`CATS: ${normalized.length} findings, stats:`, stats);

return [{ json: { ...cfg, catsResults: normalized, catsStats: stats }}];

const fs = require('fs');
const data = $input.first().json;

const output = {
  runId: data.runId,
  target: data.target,
  vulnType: data.vulnType,
  schemathesis: {
    results: data.schemathesisResults || [],
    stats: data.schemathesisStats || { total: 0, failures: 0, errors: 0, skipped: 0 },
  },
  cats: {
    results: data.catsResults || [],
    stats: data.catsStats || { total: 0, failures: 0, errors: 0, skipped: 0 },
  },
  timestamp: new Date().toISOString(),
  endpointsFile: data.endpointsFile,
  dictResultsFile: data.dictResultsFile,
  schemaResultsFile: data.schemaResultsFile,
  reportFile: data.reportFile,
  configFile: data.configFile,
  baselineFile: data.baselineFile,

  owaspCategory: data.owaspCategory,
  owaspName: data.owaspName,
  startTime: data.startTime,
};

fs.writeFileSync(data.schemaResultsFile, JSON.stringify(output, null, 2));

console.log(`Workflow 4 DONE. schemathesis=${output.schemathesis.results.length}, cats=${output.cats.results.length}`);
console.log(`File: ${data.schemaResultsFile}`);

return [{ json: output }];

const fs = require('fs');
const path = require('path');

await new Promise(r => setTimeout(r, 3000));

const cfg = $('Read Endpoints File').first().json;

// === SCHEMATHESIS ===
let schemaResults = [];
let schemaStats = { total: 0, failures: 0, errors: 0, skipped: 0 };

if (fs.existsSync(cfg.schemathesisOut)) {
  try {
    const xml = fs.readFileSync(cfg.schemathesisOut, 'utf8');

    const tsMatch = xml.match(/<testsuites[^>]*errors="(\d+)"[^>]*failures="(\d+)"[^>]*skipped="(\d+)"[^>]*tests="(\d+)"/);
    if (tsMatch) {
      schemaStats.errors   = parseInt(tsMatch[1]);
      schemaStats.failures = parseInt(tsMatch[2]);
      schemaStats.skipped  = parseInt(tsMatch[3]);
      schemaStats.total    = parseInt(tsMatch[4]);
    }

    const re = /<testcase\s+name="([^"]*)"\s+time="([^"]*)"[^>]*>([\s\S]*?)<\/testcase>/g;
    let m;
    while ((m = re.exec(xml)) !== null) {
      const isFail  = m[3].includes('<failure');
      const isError = m[3].includes('<error');
      if (!isFail && !isError) continue;

      const parts = m[1].split(' ');
      const msgMatch = m[3].match(/<(?:failure|error)[^>]*>([\s\S]*?)<\/(?:failure|error)>/);
      schemaResults.push({
        tool: 'schemathesis',
        method: parts[0],
        endpoint: parts.slice(1).join(' ') || m[1],
        payload: m[1],
        status: 0, length: 0,
        time_ms: Math.round((parseFloat(m[2]) || 0) * 1000),
        message: msgMatch ? msgMatch[1].replace(/\s+/g, ' ').trim().slice(0, 500) : '',
        isFailure: isFail, isError,
      });
    }

    // Если XML отдал нули — считаем по results
    if (schemaStats.total === 0) {
      schemaStats.total    = schemaResults.length;
      schemaStats.failures = schemaResults.filter(r => r.isFailure).length;
      schemaStats.errors   = schemaResults.filter(r => r.isError).length;
    }

    console.log(`Schemathesis: ${schemaResults.length} findings, stats:`, schemaStats);
  } catch (e) { console.error('Schema parse:', e.message); }
}

// === CATS ===
let catsResults = [];
let catsStats = { total: 0, failures: 0, errors: 0, skipped: 0 };

const catsDir = `/results/cats_report_${cfg.runId}`;
if (fs.existsSync(catsDir)) {
  const files = fs.readdirSync(catsDir).filter(f => f.endsWith('.xml'));

  for (const file of files) {
    try {
      const xml = fs.readFileSync(path.join(catsDir, file), 'utf8');

      // Пробуем вытащить счётчики из <testsuites>
      const m = xml.match(/<testsuites[^>]*skipped="(\d+)"[^>]*errors="(\d+)"[^>]*failures="(\d+)"[^>]*tests="(\d+)"/);
      if (m) {
        catsStats.skipped  = parseInt(m[1]);
        catsStats.errors   = parseInt(m[2]);
        catsStats.failures = parseInt(m[3]);
        catsStats.total    = parseInt(m[4]);
      }

      const re = /<testcase\s+name="([^"]*)"\s+classname="([^"]*)"[^>]*>([\s\S]*?)<\/testcase>/g;
      let tc;
      while ((tc = re.exec(xml)) !== null) {
        const isFail  = tc[3].includes('<failure');
        const isError = tc[3].includes('<error');
        if (!isFail && !isError) continue;

        const msgMatch = tc[3].match(/<(?:failure|error)[^>]*>([\s\S]*?)<\/(?:failure|error)>/);
        catsResults.push({
          tool: 'cats',
          endpoint: tc[2],
          payload: tc[1],
          status: 0,
          isFailure: isFail,
          isError: isError,
          message: msgMatch ? msgMatch[1].replace(/\s+/g, ' ').trim().slice(0, 200) : '',
        });
        if (catsResults.length >= 50) break;
      }
    } catch (e) { console.error('CATS parse:', e.message); }
  }

  // ⚠️ FALLBACK: если XML-счётчики нули — считаем по результатам
  if (catsStats.total === 0) {
    catsStats.total    = catsResults.length;
    catsStats.failures = catsResults.filter(r => r.isFailure).length;
    catsStats.errors   = catsResults.filter(r => r.isError).length;
  }

  console.log(`CATS: ${catsResults.length} findings, stats:`, catsStats);
} else {
  console.log('CATS dir not found:', catsDir);
}

return [{ json: {
  ...cfg,
  schemathesisResults: schemaResults,
  schemathesisStats: schemaStats,
  catsResults,
  catsStats,
}}];
